create extension if not exists "pgcrypto";
create table profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, headline text, summary text, years_experience int, skills jsonb default '[]', achievements jsonb default '[]', education jsonb default '[]', certifications jsonb default '[]', target_titles jsonb default '[]', preferred_locations jsonb default '[]', remote_preference text default 'any', salary_min int, industries jsonb default '[]', created_at timestamptz default now(), updated_at timestamptz default now());
create table jobs(id uuid primary key default gen_random_uuid(), source text not null, external_id text, source_url text not null, company text not null, title text not null, location text, description text not null, posted_at timestamptz, discovered_at timestamptz default now(), unique(source,external_id));
create table job_matches(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, job_id uuid references jobs(id) on delete cascade, score int not null, breakdown jsonb not null, reasons jsonb default '[]', gaps jsonb default '[]', created_at timestamptz default now(), unique(user_id,job_id));
create table applications(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, job_id uuid references jobs(id), status text default 'interested', tailored_resume text, cover_letter text, recruiter_email text, linkedin_message text, applied_at timestamptz, next_follow_up_at timestamptz, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table contacts(id uuid primary key default gen_random_uuid(), job_id uuid references jobs(id) on delete cascade, company text, name text, title text, email text, linkedin_url text, source_url text, verification_status text default 'found', confidence int check(confidence between 0 and 100), created_at timestamptz default now());
alter table profiles enable row level security;alter table job_matches enable row level security;alter table applications enable row level security;
create policy "own profile" on profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "own matches" on job_matches for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own applications" on applications for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
